import type { BlogCategory, BlogPost } from "./blog-types";

type Guide = {
  slug: string;
  title: string;
  description: string;
  date: string;
  keyword: string;
  supportingKeywords: string[];
  longTailKeywords: string[];
  category: BlogCategory;
  image: string;
  imageAlt: string;
  hook: string;
  context: string;
  workflowTitle: string;
  workflow: string;
  example: string;
  pitfall: string;
  next: string;
  quote: string;
};

